package store

import (
	"os"

	"github.com/voocel/ainovel-cli/internal/rules"
)

// UserRulesStore manages this book's normalized user-rules snapshot (meta/user_rules.json).
//
// The single runtime source of truth: both novel_context injection and the commit_chapter check read only this one copy,
// no longer re-reading the rules files (avoiding drift and divergence between two readers). The snapshot is generated by normalization when a book is opened/imported/refreshed.
type UserRulesStore struct{ io *IO }

func NewUserRulesStore(io *IO) *UserRulesStore { return &UserRulesStore{io: io} }

// Load reads meta/user_rules.json. Returns nil if it does not exist (the caller lazily generates it accordingly).
func (s *UserRulesStore) Load() (*rules.Snapshot, error) {
	s.io.mu.RLock()
	defer s.io.mu.RUnlock()
	var snap rules.Snapshot
	if err := s.io.ReadJSONUnlocked("meta/user_rules.json", &snap); err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	return &snap, nil
}

// Save saves the snapshot.
func (s *UserRulesStore) Save(snap *rules.Snapshot) error {
	s.io.mu.Lock()
	defer s.io.mu.Unlock()
	return s.io.WriteJSONUnlocked("meta/user_rules.json", snap)
}
